import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import { AppState } from 'react-native';
import { useSettingsStore } from '../store/settingsStore';

// Placeholder audio is generated by scripts/generate-sounds.mjs. To use your own, replace
// the file in assets/audio/ (or point a require() below at a new .mp3/.m4a).
const SFX = {
  tap: require('../../assets/audio/tap.wav'),
  pop: require('../../assets/audio/pop.wav'),
  yourTurn: require('../../assets/audio/yourTurn.wav'),
  roundStart: require('../../assets/audio/roundStart.wav'),
  join: require('../../assets/audio/join.wav'),
  leave: require('../../assets/audio/leave.wav'),
  tick: require('../../assets/audio/tick.wav'),
  error: require('../../assets/audio/error.wav'),
  win: require('../../assets/audio/win.wav'),
  lose: require('../../assets/audio/lose.wav'),
  gameOver: require('../../assets/audio/gameOver.wav'),
};

const MUSIC = {
  menu: require('../../assets/audio/music_menu.wav'),
  game: require('../../assets/audio/music_game.wav'),
};

export type SoundName = keyof typeof SFX;
export type MusicTrack = keyof typeof MUSIC;

/** Per-effect loudness, so a tap stays subtle next to a win fanfare. */
const SFX_VOLUME: Record<SoundName, number> = {
  tap: 0.35,
  pop: 0.6,
  yourTurn: 0.7,
  roundStart: 0.7,
  join: 0.6,
  leave: 0.5,
  tick: 0.45,
  error: 0.6,
  win: 0.8,
  lose: 0.7,
  gameOver: 0.8,
};

/** Kept low so the music sits under conversation — it's a talking game. */
const MUSIC_VOLUME = 0.22;
const FADE_MS = 600;

// ---------------------------------------------------------------------------
// Setup
// ---------------------------------------------------------------------------

let initialised = false;

/** Call once at startup. Configures the audio session and wires settings + app state. */
export function initAudio() {
  if (initialised) return;
  initialised = true;

  // Respect the iPhone silent switch, and play alongside whatever the player is already
  // listening to instead of stopping it.
  setAudioModeAsync({
    playsInSilentMode: false,
    shouldPlayInBackground: false,
    interruptionMode: 'mixWithOthers',
  }).catch(console.error);

  // Settings load from storage asynchronously — hold the music until they have, so a
  // player who muted it doesn't hear a blip on launch.
  useSettingsStore.persist.onFinishHydration(syncMusic);
  useSettingsStore.subscribe((state, prev) => {
    if (state.musicOn !== prev.musicOn) syncMusic();
  });

  AppState.addEventListener('change', (status) => {
    appActive = status === 'active';
    syncMusic();
  });
}

// ---------------------------------------------------------------------------
// Sound effects
// ---------------------------------------------------------------------------

const sfxPlayers: Partial<Record<SoundName, AudioPlayer>> = {};

/** Plays a one-shot effect, restarting it if it's already playing. Never throws. */
export function playSound(name: SoundName) {
  if (!useSettingsStore.getState().sfxOn) return;
  try {
    let player = sfxPlayers[name];
    if (!player) {
      player = createAudioPlayer(SFX[name]);
      player.volume = SFX_VOLUME[name];
      sfxPlayers[name] = player;
    }
    // expo-audio players stay paused at the end once finished — rewind before replaying.
    player.seekTo(0).catch(() => {});
    player.play();
  } catch (e) {
    console.warn(`sound "${name}" failed`, e);
  }
}

// ---------------------------------------------------------------------------
// Music
// ---------------------------------------------------------------------------

let appActive = AppState.currentState === 'active';
let wantedTrack: MusicTrack | null = null;
let current: { track: MusicTrack; player: AudioPlayer } | null = null;
const fades = new Map<AudioPlayer, ReturnType<typeof setInterval>>();

function fade(player: AudioPlayer, to: number, onDone?: () => void) {
  clearInterval(fades.get(player));
  const from = player.volume;
  const steps = Math.max(1, Math.round(FADE_MS / 50));
  let step = 0;
  const interval = setInterval(() => {
    step += 1;
    try {
      player.volume = from + ((to - from) * step) / steps;
    } catch {
      step = steps; // player already released
    }
    if (step >= steps) {
      clearInterval(interval);
      fades.delete(player);
      onDone?.();
    }
  }, 50);
  fades.set(player, interval);
}

function fadeOutAndRelease(player: AudioPlayer) {
  fade(player, 0, () => {
    try {
      player.pause();
      player.remove();
    } catch {}
  });
}

/** Brings playback in line with the wanted track, the music setting and app state. */
function syncMusic() {
  const shouldPlay =
    wantedTrack !== null &&
    appActive &&
    useSettingsStore.persist.hasHydrated() &&
    useSettingsStore.getState().musicOn;
  try {
    if (!shouldPlay) {
      if (current) {
        const { player } = current;
        fade(player, 0, () => {
          try { player.pause(); } catch {}
        });
      }
      return;
    }
    if (current && current.track !== wantedTrack) {
      fadeOutAndRelease(current.player);
      current = null;
    }
    if (!current) {
      const player = createAudioPlayer(MUSIC[wantedTrack!]);
      player.loop = true;
      player.volume = 0;
      current = { track: wantedTrack!, player };
    }
    current.player.play();
    fade(current.player, MUSIC_VOLUME);
  } catch (e) {
    console.warn('music failed', e);
  }
}

/** Switches the background music, crossfading from whatever's playing. `null` fades it out. */
export function setMusicTrack(track: MusicTrack | null) {
  if (track === wantedTrack) return;
  wantedTrack = track;
  syncMusic();
}
